var EXTRA=[{dot:"gray",j:"Sensors",h:"Dopo LCA, forza eccentrica più bassa nell'arto operato: squat con volano",v:"Studio trasversale piccolo su atleti di squadra: la differenza fra gli arti emerge nella fase eccentrica e non nell'attività elettromiografica convenzionale; gli autori stessi definiscono esplorativa la misura di entropia e chiedono campioni più grandi.",pmid:'42817281',doi:'10.3390/s26185745',temi:["LCA","forza eccentrica","riabilitazione"]},{dot:"gray",j:"PLoS One",h:"Acido ialuronico-sorbitolo nel dolore femororotuleo degli atleti: miglioramento senza gruppo di controllo",v:"Studio prospettico a braccio unico, non randomizzato: i punteggi migliorano a sei mesi, ma senza controllo l'effetto non si attribuisce all'iniezione; il sottogruppo con indice di massa corporea elevato è piccolo e un autore afferisce ad Aptissen SA (conflitti di interesse non letti).",pmid:'42814735',doi:'10.1371/journal.pone.0346269',temi:["dolore femororotuleo","acido ialuronico","atleti"]},{dot:"gray",j:"The Journal of Bone and Joint Surgery",h:"Ormone della crescita e apofisi tibiale: la risonanza con diffusione mostra cambiamenti precoci",v:"Coorte prospettica multicentrica in bambini scheletricamente immaturi (livello II): la diffusione nella tuberosità tibiale cambia dopo l'avvio della terapia, con un massimo dopo diversi mesi; è un marcatore di imaging e non misura le avulsioni.",pmid:'42821635',doi:'10.2106/JBJS.26.00599',temi:["tuberosità tibiale","scheletricamente immaturo","risonanza magnetica"]},{dot:"gray",j:"Anesthesiology",h:"Oppioidi a rilascio prolungato dopo protesi: poco più uso persistente e più accessi in pronto soccorso",v:"Studio di popolazione in Ontario con ponderazione per propensione: associazioni piccole ma coerenti con più uso persistente, riammissioni e accessi in pronto soccorso, con costi totali più bassi; osservazionale e riferito insieme a protesi d'anca e di ginocchio.",pmid:'42808787',doi:'10.1097/ALN.0000000000006400',temi:["protesi di ginocchio","oppioidi","analgesia"]},{dot:"gray",j:"Academic Radiology",h:"Spessore automatico della cartilagine alla risonanza: accordo accettabile dopo calibrazione",v:"Convalida tecnica contro le misure manuali del radiologo: l'automatico sovrastima in modo sistematico e, dopo una calibrazione globale, l'accordo diventa paragonabile alla variabilità fra sequenze, con la variabilità maggiore in rotula e tibia laterale; non è un esito clinico.",pmid:'42823317',doi:'10.1016/j.acra.2026.09.025',temi:["risonanza magnetica","cartilagine","segmentazione automatica"]},{dot:"gray",j:"Frontiers in Medicine",h:"PRP nell'apparato muscolo-scheletrico: rassegna narrativa, efficacia che dipende dall'indicazione",v:"Gli autori stessi scrivono che la sintesi è interpretativa, senza protocollo né valutazione del rischio di bias: per il ginocchio indicano un possibile beneficio selezionato nell'artrosi lieve-moderata, più debole dove esistono dati controllati con placebo.",pmid:'42812934',doi:'10.3389/fmed.2026.1920226',temi:["PRP","artrosi","iniezioni intra-articolari"]},{dot:"gray",j:"BMJ",h:"Editoriale sulla chirurgia robotica di anca e ginocchio: «alta tecnologia, ma è meglio?»",v:"Editoriale di Järvinen, Vänni e Karjalainen: l'abstract non è disponibile e il testo non è stato aperto, quindi la risposta degli autori alla domanda del titolo non è verificata.",pmid:'42823058',doi:'10.1136/bmj-2926-100981',temi:["protesi robotica","VELYS","evidenza"]},{dot:"gray",j:"The American Journal of Sports Medicine",h:"Lettera sull'artroplastica rotulo-femorale robotica nei giovani e sul ritorno allo sport",v:"Lettera all'editore, con risposta degli autori in un'altra voce: nessun abstract, testo non letto e articolo originale non aperto, quindi non si sa quali dati siano discussi.",pmid:'42817606',doi:'10.1177/03635465261480097',temi:["artroplastica rotulo-femorale","protesi robotica","ritorno allo sport"]}];
var SCOPERTE=[{t:"Elettroagopuntura con ago gigante prima dell'intervento per il dolore dopo la protesi di ginocchio",v:"Un gruppo di Shanghai (Guanghua Hospital, medicina tradizionale cinese) confronta in un RCT l'elettroagopuntura prima e dopo l'operazione con una finta, sull'arto non operato: chi la riceve prima riferisce meno dolore nei primi giorni. Vale la deviazione perché è un modo non farmacologico di anticipare il dolore; il follow-up dura una settimana e il campione è piccolo.",pmid:'42803050',doi:'10.12200/j.issn.1003-0034.20250200',temi:["agopuntura","protesi di ginocchio","medicina tradizionale cinese"]},{t:"Una risonanza che misura la diffusione nella cartilagine: artrosi precoce e progressione radiografica",v:"Un gruppo della New York University mostra in uno studio prospettico che la diffusività media nel condilo femorale mediale distingue le ginocchia con artrosi precoce meglio del T2 mapping e migliora la previsione della progressione a tre anni. Vale la deviazione perché porta l'imaging dalla forma alla microstruttura; il campione è piccolo, la validazione solo interna e non dice che cosa fare.",pmid:'42817870',doi:'10.1002/jmri.70562',temi:["risonanza magnetica","cartilagine","biomarcatori"]},{t:"Il muscolo articolare del ginocchio esiste davvero come muscolo a sé?",v:"Una rassegna narrativa giapponese (Kurume University) riesamina otto studi anatomici: origine e inserzione coincidono, ma numero di fasci, strati e continuità con il vasto intermedio no, per una definizione anatomica non condivisa. Vale la deviazione perché tocca come si leggono la risonanza, il dolore anteriore e l'accesso protesico; è anatomia descrittiva, senza dati clinici.",pmid:'42817925',doi:'10.1002/ca.70236',temi:["anatomia","vasto intermedio","dolore anteriore"]}];
var SOC={"1":{"video":"Riparazione del legamento crociato anteriore con nastro di rinforzo: che posto ha accanto alla ricostruzione? Una rassegna di studi, uscita a settembre 2026, riesamina quando si può riattaccare il legamento invece di sostituirlo con un tendine. Funziona nelle rotture recenti e vicine all'attacco sul femore, con tessuto ancora buono: circa quattro su dieci in una serie di trecentocinquantatré risonanze; più della metà delle rotture è a metà legamento, e di solito richiede la ricostruzione. Negli studi citati il legamento si è rotto di nuovo in circa una persona su dieci a tre anni e in quasi due su dieci a cinque anni, più spesso nei giovani. Il limite: gli studi sono piccoli e non assegnano i pazienti a caso, quindi non si può dire che riparare e ricostruire siano equivalenti. È una scelta per casi selezionati.","linkedin":"Riparazione primaria del LCA con suture tape: rassegna narrativa (Frontiers in Sports and Active Living, settembre 2026, testo completo aperto) sul perimetro della tecnica. Candidate: lesioni acute prossimali Sherman I e II con residuo riducibile e buon tessuto; in una prevalenza riportata su 353 lesioni acute in RM, I+II = 43%, a metà legamento 52%.\n\nDagli studi citati: fallimento 10,7% su 56 a 3,2 anni; 17,6% su 34 a 5 anni (KOOS da 48,7 a 88,5), più frequente nei giovani e con Marx iniziale alto; 26,1% in militari. Nei trial sulla stabilizzazione dinamica intralegamentosa, tecnica distinta, re-rottura 8,7% contro 19,0% con ricostruzione all-inside. Senza intervalli di confidenza.\n\nLimite: rassegna narrativa senza protocollo né valutazione del rischio di bias, studi piccoli e per lo più non randomizzati; nessun dato su innesto quadricipitale o LET. Conclusione degli autori: strategia di preservazione selettiva, non un sostituto della ricostruzione.","instagram":"🦵 Crociato anteriore: riattaccare il legamento invece di sostituirlo è possibile solo in rotture scelte, recenti e vicine all'attacco sul femore.\n\nNegli studi citati da una rassegna di settembre 2026 si è rotto di nuovo in circa una persona su dieci a tre anni e in quasi due su dieci a cinque, più spesso nei giovani.\n\nStudi piccoli e non randomizzati: non è equivalente a ricostruire. La scelta dipende dalla rottura e si discute con il chirurgo.","pazienti":"Se il legamento crociato anteriore si rompe, a volte si può riattaccarlo invece di sostituirlo con un tendine. Una rassegna di studi, uscita a settembre 2026, spiega che vale per una parte minoritaria dei casi: rotture recenti, vicine all'attacco sull'osso della coscia, con tessuto ancora buono. Negli studi citati il legamento si è rotto di nuovo in circa una persona su dieci a tre anni e in quasi due su dieci a cinque anni, più spesso nei più giovani e negli sportivi. Gli studi sono pochi e piccoli e non permettono di dire che le due strade siano equivalenti: la scelta dipende dal tipo di rottura e si discute con il chirurgo."}};
var SOCV={"1":{"video":{"chir":["Riparazione primaria del LCA con nastro di sutura: che posto ha accanto alla ricostruzione? Una rassegna narrativa con testo completo aperto, su Frontiers in Sports and Active Living a settembre 2026, riesamina indicazioni, predittori di fallimento ed esiti. Le lesioni candidate sono acute e prossimali, Sherman tipo uno e due, con residuo riducibile, buon tessuto e rivestimento sinoviale conservato. Nella prevalenza riportata da risonanza su 353 lesioni acute, i tipi uno e due sommano il 43%; il 52% è a metà legamento.","I numeri sono quelli degli studi citati, senza intervalli di confidenza. Fallimento del 10,7% su 56 riparazioni a 3,2 anni; 17,6% su 34 pazienti a 5 anni, con KOOS da 48,7 a 88,5 e re-rotture più frequenti nei più giovani e con attività più alta; 26,1% in una coorte militare. Nei trial sulla stabilizzazione dinamica intralegamentosa, tecnica distinta, la re-rottura è 8,7% contro 19,0% con la ricostruzione all-inside.","Il limite: rassegna narrativa, senza protocollo registrato né valutazione del rischio di bias; studi piccoli e per lo più non randomizzati, che gli stessi autori giudicano insufficienti per concludere un'equivalenza con la ricostruzione. Nessuno studio citato riguarda innesto quadricipitale o rinforzo laterale. La conclusione: strategia di preservazione selettiva, non un sostituto della ricostruzione del LCA."],"misto":["Rottura del legamento crociato anteriore: si può riattaccare invece di ricostruire? Una rassegna di studi, pubblicata a settembre 2026, riesamina la riparazione con un nastro di rinforzo. Funziona nelle rotture recenti e vicine all'attacco sul femore, con tessuto ancora buono. In una serie di risonanze su 353 rotture acute, circa quattro su dieci avevano questa sede; più della metà era a metà legamento, dove la riparazione di solito non è indicata.","Negli studi citati il legamento si è rotto di nuovo nel 10,7% di 56 casi a poco più di tre anni, e nel 17,6% di 34 pazienti a cinque anni; nello stesso studio a cinque anni i punteggi del ginocchio sono saliti da 48,7 a 88,5. Le nuove rotture sono state più frequenti nei più giovani e in chi fa sport con cambi di direzione; in una coorte militare sono arrivate al 26,1%.","Il limite: è una rassegna senza un calcolo unico dei risultati, con studi piccoli che non assegnano i pazienti a caso, quindi non si può dire che riparare sia equivalente a ricostruire. Gli autori concludono che è una scelta selettiva e non una sostituzione, e che la decisione dipende dal tipo di rottura e dalla persona."],"pazienti":["Se il legamento crociato anteriore si rompe, a volte si può riattaccarlo invece di sostituirlo con un tendine. Una rassegna di studi, uscita a settembre 2026, spiega quando. Funziona soprattutto nelle rotture recenti e vicine all'attacco sull'osso della coscia, dove il tessuto è ancora buono. Sono una parte minoritaria dei casi: più della metà delle rotture avviene a metà del legamento e di solito richiede la ricostruzione.","Negli studi citati, dopo la riparazione il legamento si è rotto di nuovo in circa una persona su dieci a tre anni in uno studio e in quasi due su dieci a cinque anni in un altro. Le nuove rotture sono state più frequenti nei più giovani e in chi pratica sport con molti cambi di direzione. Nello stesso studio a cinque anni i punteggi del ginocchio sono saliti in media.","Il limite: gli studi sono pochi e piccoli, non confrontano in modo diretto riparazione e ricostruzione e non permettono di dire che siano equivalenti. Gli autori scrivono che la riparazione è una scelta per casi selezionati. Quale strada sia adatta dipende dal tipo di rottura e dalla persona, e se ne parla con il chirurgo."]},"linkedin":{"chir":["Riparazione primaria del LCA con suture tape: una rassegna narrativa (Frontiers in Sports and Active Living, settembre 2026, testo completo aperto) ne ridefinisce il perimetro. Candidate: lesioni acute prossimali Sherman I e II con residuo riducibile e buon tessuto; su 353 lesioni acute in RM, I+II = 43%, a metà legamento 52%.","Dagli studi citati: fallimento 10,7% su 56 a 3,2 anni; 17,6% su 34 a 5 anni (KOOS da 48,7 a 88,5), più frequente nei giovani e con Marx iniziale alto; 26,1% in militari. Senza intervalli di confidenza.","Limite: rassegna narrativa senza protocollo né rischio di bias, studi piccoli e per lo più non randomizzati, nessun dato su innesto quadricipitale o LET. Conclusione degli autori: preservazione selettiva, non un sostituto della ricostruzione."],"misto":["Riparare il legamento crociato anteriore invece di ricostruirlo: una rassegna di studi (settembre 2026) indica per chi è possibile. Rotture recenti, vicine all'attacco sul femore, con tessuto buono: circa quattro su dieci in una serie di 353 risonanze.","Negli studi citati il legamento si è rotto di nuovo nel 10,7% di 56 casi a poco più di tre anni e nel 17,6% di 34 pazienti a cinque anni, più spesso nei giovani e negli sportivi con cambi di direzione.","Il limite: rassegna senza calcolo unico, studi piccoli e non randomizzati; non si può dire che riparare equivalga a ricostruire. È una scelta per casi selezionati."],"pazienti":["Rottura del legamento crociato anteriore: a volte si può riattaccarlo invece di sostituirlo. Una rassegna di studi (settembre 2026) mostra che riguarda una parte minoritaria dei casi: rotture recenti, vicine all'attacco sulla coscia, con tessuto ancora buono.","Negli studi citati il legamento si è rotto di nuovo in circa una persona su dieci a tre anni e in quasi due su dieci a cinque anni, più spesso nei più giovani e negli sportivi.","Gli studi sono pochi e piccoli e non permettono di dire che le due strade siano equivalenti: la scelta dipende dalla rottura e si discute con il chirurgo."]},"instagram":{"chir":["🦵 Riparazione primaria del LCA con suture tape: strategia selettiva, non un sostituto della ricostruzione (rassegna narrativa, Frontiers in Sports and Active Living, settembre 2026).","Fallimento 10,7% su 56 a 3,2 anni; 17,6% su 34 a 5 anni; più alto nei giovani e nell'alta richiesta. Nessun IC riportato.","Limite: studi piccoli, non randomizzati; nessun dato su innesto quadricipitale o LET."],"misto":["🦵 Crociato anteriore: riattaccare il legamento è possibile solo in rotture scelte, recenti e vicine all'attacco sul femore.","Negli studi citati si è rotto di nuovo in circa una persona su dieci a tre anni e in quasi due su dieci a cinque, più spesso nei giovani.","Studi piccoli e non randomizzati: non è equivalente a ricostruire, è una scelta per casi selezionati."],"pazienti":["🦵 Crociato anteriore: a volte il legamento si può riattaccare invece di sostituirlo, ma solo in alcune rotture.","Negli studi, la nuova rottura è stata più frequente nei più giovani e negli sportivi.","Gli studi sono pochi e piccoli: la scelta dipende dal tipo di rottura e si discute con il chirurgo."]},"reel":{"chir":["[RIPARAZIONE LCA] Suture tape: rassegna narrativa, testo completo aperto, settembre 2026.","[I NUMERI] Fallimento 10,7% su 56 a 3,2 anni; 17,6% su 34 a 5 anni; nessun IC.","[IL LIMITE] Studi piccoli, non randomizzati; strategia selettiva, non un sostituto."],"misto":["[CROCIATO] Riattaccare il legamento invece di ricostruirlo? Solo in rotture scelte.","[I NUMERI] Nuova rottura in circa una persona su dieci a tre anni, quasi due su dieci a cinque.","[IL LIMITE] Studi piccoli e non randomizzati."],"pazienti":["[CROCIATO] Riattaccare il legamento invece di sostituirlo: a volte è possibile.","[CHE COSA DICONO GLI STUDI] Vale per una parte minoritaria delle rotture.","[IL LIMITE] Gli studi sono pochi e piccoli: se ne parla con il chirurgo."]}}};
var TAGS={"1":{"linkedin":"#Ortopedia #LegamentoCrociato #MedicinaDelloSport","instagram":"#ortopedia #ginocchio #legamentocrociato #crociatoanteriore #chirurgiaortopedica #medicinadellosport #riabilitazione #ortopediaticino #medicinabasatasulleprove","kw":"riparazione legamento crociato anteriore, rottura crociato ginocchio, ricostruzione crociato"}};
var NLB={"1":{"prof":["Riparazione primaria del LCA con suture tape: una scelta selettiva, non un sostituto","Una rassegna narrativa con testo completo aperto (Frontiers in Sports and Active Living, settembre 2026) riporta, da studi singoli, fallimenti del 10,7% su 56 riparazioni con nastro di sutura a 3,2 anni e del 17,6% su 34 pazienti a 5 anni, più frequenti nei giovani e nell'alta richiesta; nella prevalenza riportata da risonanza su 353 lesioni acute, il 16% è prossimale di tipo I, il 27% di tipo II e il 52% a metà legamento. Gli autori concludono che è una strategia selettiva e non un sostituto della ricostruzione.","Nota critica: rassegna narrativa senza protocollo né valutazione del rischio di bias, con studi piccoli e per lo più non randomizzati; i dati non permettono conclusioni di equivalenza con la ricostruzione e non riguardano né l'innesto quadricipitale né il rinforzo laterale."],"mix":["Crociato anteriore: riattaccare il legamento invece di ricostruirlo vale solo per rotture scelte","Una rassegna di studi sul riattaccare il legamento crociato anteriore con un nastro di rinforzo, invece di sostituirlo con un tendine, riporta che questa strada riguarda rotture vicine all'attacco sul femore, recenti e con tessuto di buona qualità, circa quattro su dieci in una serie di risonanze. Negli studi citati il legamento si è rotto di nuovo in circa una persona su dieci a tre anni in uno studio e in quasi due su dieci a cinque anni in un altro, più spesso nei giovani e in chi pratica sport con cambi di direzione.","Nota sul limite: è una rassegna senza un calcolo unico dei risultati; gli studi sono piccoli e non assegnano i pazienti a caso, quindi non si può dire che riparare sia equivalente a ricostruire."],"paz":["Crociato anteriore: riattaccare il legamento è possibile solo in alcune rotture","Per alcune rotture del legamento crociato anteriore, recenti e vicine all'attacco sull'osso della coscia, è possibile riattaccare il legamento invece di sostituirlo. Una revisione degli studi mostra che questa strada riguarda una parte minoritaria dei casi e che in alcuni studi il legamento si è rotto di nuovo, più spesso nei più giovani e negli sportivi. La scelta dipende dal tipo di rottura e viene valutata dal chirurgo.","Gli studi sono pochi e piccoli, non confrontano in modo diretto le due strade e non permettono di dire che siano equivalenti."],"kw":"legamento crociato anteriore riparazione, rottura crociato, intervento crociato ginocchio"},"2":{"prof":["LCA primario: nel valore a 2 anni pesano innesto e tempo operatorio, non il costo totale","In un'analisi retrospettiva di 491 ricostruzioni primarie del LCA di 24 chirurghi in un centro ambulatoriale statunitense (Orthopedics, ottobre 2026), costi totali e variazione del KOOS a 2 anni risultano poco correlati (coefficiente 0,14); tempo operatorio, riparazione meniscale concomitante, tipo di innesto e impianti si associano al valore, con l'alloinnesto inferiore agli autoinnesti (p=0,003).","Nota critica: dati retrospettivi di un solo sistema statunitense, tipo di coefficiente e intervalli non riportati nell'abstract, autoinnesti non distinti e costi non trasferibili alla Svizzera."],"mix":["Crociato anteriore: costi più alti non si associano a punteggi più alti a due anni","In un centro americano, 491 persone operate di ricostruzione del legamento crociato anteriore da 24 chirurghi sono state seguite per due anni: la spesa complessiva e il miglioramento dei punteggi del ginocchio sono risultati poco collegati. Il rapporto fra miglioramento e costo è stato più basso con l'innesto da donatore rispetto a quello prelevato dal paziente, e dipende anche dalla durata dell'intervento e dalla riparazione del menisco eseguita nello stesso tempo.","Nota sul limite: i dati vengono da un solo sistema sanitario con costi diversi da quelli svizzeri, e non si può escludere che i casi più complessi siano capitati più spesso a certi chirurghi o a certi innesti."],"paz":["Crociato anteriore: un intervento più costoso non ha dato punteggi più alti a due anni","Uno studio su 491 persone operate al legamento crociato anteriore in un centro americano ha confrontato quanto è costata la cura e quanto sono migliorati i punteggi del ginocchio dopo due anni: le due cose sono risultate poco collegate. L'innesto da donatore ha dato un rapporto fra miglioramento e costo più basso di quello prelevato dalla persona stessa.","Lo studio guarda indietro nel tempo in un solo centro e non permette di sapere quale scelta sia adatta a una singola persona: se ne parla con il proprio chirurgo."],"kw":"costo intervento crociato anteriore, legamento crociato innesto, ricostruzione LCA risultati"},"3":{"prof":["LCA leso: meno forza in estensione, più co-contrazione degli ischiocrurali, correlate al KOOS","In 114 pazienti con rottura isolata del LCA (55 acuti, 59 cronici) e 57 controlli (Frontiers in Medicine, settembre 2026), la coppia di picco in estensione dell'arto leso è più bassa che nei controlli (uomini 2,23 ± 0,64 negli acuti e 3,05 ± 0,60 nei cronici contro 3,48 ± 0,59 N·m/kg, p ≤ 0,001) e la co-contrazione combinata degli ischiocrurali è più alta, con il massimo nei cronici (uomini 23,05 ± 5,87% contro 7,89 ± 4,34%, p < 0,001); entrambe si correlano ai sottopunteggi KOOS.","Nota critica: studio trasversale su pazienti non operati e non gli stessi nel tempo; la correlazione con il KOOS è moderata e non indica se la co-contrazione sia causa o compenso."],"mix":["Rottura del crociato: meno forza davanti alla coscia e più contrazione dei muscoli dietro","In 114 persone con rottura del legamento crociato anteriore e in 57 persone sane, misurate con un dinamometro e con elettrodi sulla pelle, la forza dei muscoli davanti alla coscia è più bassa nel ginocchio leso, soprattutto nelle prime settimane e in misura minore ma ancora visibile dopo sei mesi, mentre i muscoli dietro la coscia si contraggono di più insieme a quelli davanti, soprattutto nella rottura non recente. Più la forza è bassa e la contrazione dei muscoli dietro è alta, peggiori sono i punteggi riferiti dalla persona sul proprio ginocchio.","Nota sul limite: lo studio fotografa persone diverse in momenti diversi e non operate, quindi non dice se questi muscoli siano la causa dei sintomi o un adattamento, né che cosa accada dopo l'intervento."],"paz":["Dopo la rottura del crociato la coscia perde forza davanti e lavora di più dietro","Uno studio cinese ha misurato la forza e l'attività dei muscoli della coscia in persone con rottura del legamento crociato anteriore e in persone sane. Nel ginocchio leso la forza davanti è più bassa e i muscoli dietro lavorano di più insieme a quelli davanti; questi valori si sono accompagnati a punteggi più bassi di funzione del ginocchio riferiti dalle persone.","Lo studio confronta gruppi diversi in un solo momento: mostra un'associazione e non dice che cosa sia causa e che cosa sia effetto."],"kw":"rottura crociato anteriore forza coscia, riabilitazione crociato, quadricipite dopo crociato"},"4":{"prof":["Ginocchio nativo: sotto carico la linea articolare non è neutra, la geometria orienta l'allineamento","Una revisione sistematica descrittiva di 39 studi su ginocchio nativo adulto, con imaging in vivo e cadavere (The Knee, ottobre 2026), riporta che sotto carico la superficie mediale della tibia prossimale diventa più parallela al suolo, che la compressione assiale produce varo e traslazione mediale nella flessione precoce e che slope tibiale posteriore e posizione antero-posteriore del contatto sono legati a rotazione e sublussazione; non sono riportati dati quantitativi aggregati.","Nota critica: ricerca su un «ampio corpus» senza database dichiarati nell'abstract, mappa senza graduazione della qualità, solo ginocchia native e nessun esito clinico."],"mix":["Il ginocchio sano sotto carico non è «dritto»: la forma delle superfici orienta la gamba","Una rassegna di 39 studi su ginocchia non operate, con immagini fatte sotto carico e prove su cadavere, descrive che sotto peso la superficie interna dell'osso tibiale si dispone più parallela al suolo e che la forma delle superfici, compresa l'inclinazione all'indietro del piatto tibiale, influenza come il ginocchio si piega e scorre. Gli autori ne ricavano che l'allineamento del ginocchio va letto insieme al modo in cui si carica, non solo da fermo.","Nota sul limite: è una mappa descrittiva, senza numeri complessivi, che riguarda ginocchia non operate e con menisco conservato, e non dice come cambiare un intervento."],"paz":["Il ginocchio sano cambia posizione sotto peso: la forma delle ossa conta","Una revisione di studi su ginocchia non operate mostra che, quando ci si carica sopra, la forma delle superfici dell'osso influenza come il ginocchio si orienta e scorre. Per questo la misura dell'asse della gamba fatta da fermi può non raccontare tutta la storia.","È una rassegna descrittiva, senza numeri complessivi e senza risultati sui pazienti operati."],"kw":"allineamento ginocchio, slope tibiale, asse della gamba ginocchio"},"5":{"prof":["Protesi totale: bupivacaina liposomiale con blocco adduttori e iPACK, VAS a 24 ore −0,52 punti","In un RCT monocentrico su 60 pazienti (Drug Design, Development and Therapy, settembre 2026), la VAS a riposo a 24 ore è 2,4 ± 0,8 con bupivacaina liposomiale e 2,9 ± 1,1 con bupivacaina cloridrato più desametasone (differenza −0,52; IC 95% da −1,01 a −0,02; p=0,040); l'analgesia di soccorso è più frequente col desametasone (RR 2,40; IC 95% 1,12-5,14).","Nota critica: l'IC sfiora lo zero e la soglia clinica non è riportata, il confronto cambia due variabili insieme, 60 pazienti in un centro, nessuna correzione per confronti multipli dichiarata nell'abstract."],"mix":["Dopo la protesi di ginocchio: un anestetico a rilascio lento riduce di poco il dolore a un giorno","In 60 persone operate di protesi totale di ginocchio, divise a caso in due gruppi, un anestetico locale a rilascio lento infiltrato attorno al ginocchio ha dato, dopo un giorno, un dolore a riposo di poco più basso (circa mezzo punto) rispetto a un anestetico di uso comune associato a cortisone, e nelle ore successive meno persone hanno chiesto farmaci di soccorso. Gli autori stessi invitano a valutare con cautela quanto conti questa differenza.","Nota sul limite: i due gruppi differivano per due elementi insieme, il gruppo è piccolo e la differenza minima compatibile con i dati è vicina allo zero, quindi non si può dire con certezza che sia rilevante."],"paz":["Dopo la protesi di ginocchio: un anestetico a rilascio lento ha dato poco dolore in meno","Sessanta persone operate di protesi di ginocchio hanno ricevuto, a sorte, uno di due schemi di anestetico locale attorno al ginocchio. Con quello a rilascio lento il dolore dopo un giorno è risultato leggermente più basso, di circa mezzo punto, e meno persone hanno avuto bisogno di farmaci in più. Gli autori stessi ricordano che non è chiaro quanto questa differenza conti nella vita di tutti i giorni.","Lo studio è piccolo e svolto in un solo centro: i risultati non valgono per tutti e la scelta dell'anestesia spetta all'équipe che segue la persona."],"kw":"dolore dopo protesi ginocchio, anestesia locale protesi, blocco nervoso ginocchio"},"6":{"prof":["Registro irlandese 2015-2024: protesi totale di ginocchio, OKS da 19,5 a 40,5 a 5 anni","Il primo decennio dell'Irish National Orthopaedic Register (International Orthopaedics, settembre 2026) riporta 43.291 interventi in 17 ospedali, di cui 18.102 protesi totali di ginocchio primarie: Oxford Knee Score medio da 19,5 a 40,5 a cinque anni, revisione a un anno 0,8%, infezione del sito a 30 giorni 0,5%.","Nota critica: dati aggregati e descrittivi, copertura nazionale incompleta e denominatore delle revisioni incompleto come dichiarato dagli autori, nessuna distinzione fra robot e tecnica manuale, revisione a un solo anno."],"mix":["Protesi di ginocchio in Irlanda: i punteggi salgono da 19,5 a 40,5 in cinque anni","Il registro nazionale irlandese delle protesi, nei suoi primi dieci anni, ha raccolto oltre 43.000 interventi di anca e ginocchio in 17 ospedali, di cui circa 18.000 protesi totali di ginocchio primarie. Il punteggio del ginocchio è passato in media da 19,5 a 40,5 a cinque anni, circa otto protesi su mille sono state rioperate entro un anno e le infezioni della ferita nel primo mese sono state cinque su mille.","Nota sul limite: il registro non copre tutti gli ospedali e i numeri sulle revisioni vanno letti con cautela; non distingue le tecniche e segue le protesi per un solo anno."],"paz":["Protesi di ginocchio: in un registro irlandese i punteggi salgono a cinque anni","Un registro irlandese ha raccolto dieci anni di interventi di protesi di anca e di ginocchio. Per il ginocchio, il punteggio che misura dolore e funzione è passato in media da 19,5 prima dell'intervento a 40,5 dopo cinque anni; circa otto protesi su mille hanno richiesto un nuovo intervento entro un anno.","Il registro raccoglie solo una parte degli ospedali del Paese e segue le protesi per un anno: non dice come andrà ogni persona."],"kw":"protesi ginocchio registro, durata protesi ginocchio, protesi totale ginocchio risultati"},"7":{"prof":["Adesiolisi artroscopica dopo protesi: flessione −4,85° contro −15,98° con chirurgo con fellowship","In 94 adesiolisi artroscopiche per rigidità dopo protesi totale (Mayo Clinic, Arthroscopy, Sports Medicine, and Rehabilitation, settembre 2026), la perdita di flessione rispetto al valore intraoperatorio è 4,85° con chirurgo con fellowship in artroscopia e 15,98° senza (p=0,006); rispetto a prima della protesi, flessione +1,66° contro −21,76° (p<0,001); revisioni 8 su 94, 6 nel gruppo senza fellowship.","Nota critica: coorte retrospettiva su 36 anni, la formazione del chirurgo è confusa con volume, epoca e selezione; con 8 revisioni (2/46 contro 6/48, RR 0,35, IC 95% 0,07-1,64) il confronto è muto."],"mix":["Ginocchio rigido dopo protesi: il movimento guadagnato in artroscopia si perde in parte","In 94 ginocchi operati in artroscopia per liberare le aderenze dopo una protesi, la flessione guadagnata in sala si è mantenuta meglio quando il chirurgo aveva una formazione specifica in artroscopia: perdita media di circa 5 gradi contro circa 16 gradi nel tempo. Anche le protesi rifatte dopo l'intervento sono state numericamente meno frequenti in questo gruppo, ma in totale sono otto, troppo poche per un confronto.","Nota sul limite: lo studio guarda indietro in un solo sistema su oltre trent'anni; la formazione del chirurgo si intreccia con altre differenze, quindi indica un'associazione e non una causa."],"paz":["Ginocchio rigido dopo protesi: l'artroscopia libera il movimento, ma una parte si perde","Dopo una protesi di ginocchio può comparire rigidità, e un intervento in artroscopia può liberare le aderenze. In uno studio su 94 interventi, parte del movimento guadagnato in sala si è persa col tempo, in misura minore quando il chirurgo aveva una formazione specifica in artroscopia.","Lo studio guarda al passato in un solo sistema e non basta a dire quale chirurgo o quale intervento sia adatto a una singola persona."],"kw":"rigidità dopo protesi ginocchio, artrofibrosi ginocchio, ginocchio rigido dopo protesi"},"8":{"prof":["Atterraggio monopodalico e LCA: carichi relativi più alti nei pre-puberi che nelle post-puberi","In uno studio di laboratorio su 69 giovani (Journal of Sports Sciences, ottobre 2026), con motion capture e pedane di forza su salto monopodalico e cambio di direzione, le ragazze post-puberi non mostrano biomeccanica indicativa di un rischio di LCA più alto, mentre i pre-puberi hanno forze verticali di reazione e momenti al ginocchio relativi maggiori; gli autori suggeriscono screening e prevenzione prima della pubertà.","Nota critica: 9-16 partecipanti per gruppo, nessuna statistica nell'abstract, nessun infortunio osservato, indicatore indiretto di rischio: il risultato nelle post-puberi è muto."],"mix":["Rischio di crociato nei giovani: nel salto su una gamba i carichi più alti sono prima della pubertà","In 69 ragazze e ragazzi misurati in laboratorio mentre atterrano su una gamba e cambiano direzione, le ragazze dopo la pubertà non hanno mostrato i movimenti che di solito si associano a un rischio più alto di rottura del crociato, mentre i bambini prima della pubertà hanno mostrato carichi relativi più alti sul ginocchio. Gli autori propongono di fare prevenzione prima, non dopo, la maturazione.","Nota sul limite: i gruppi sono piccoli, nessuno si è fatto male durante lo studio e i movimenti sono solo un indizio del rischio, quindi non si può escludere una differenza che qui non si vede."],"paz":["Crociato nei giovani: la prevenzione può cominciare prima della pubertà","Uno studio di laboratorio ha osservato come atterrano su una gamba 69 ragazze e ragazzi a diversi stadi della crescita. I più piccoli, prima della pubertà, hanno mostrato carichi relativi più alti sul ginocchio; le ragazze dopo la pubertà non hanno mostrato i movimenti attesi per un rischio maggiore. Gli autori ritengono utile insegnare movimenti sicuri prima.","Lo studio è piccolo, non ha seguito nessuno nel tempo e non dice chi si farà male: la prevenzione si decide con l'allenatore e con il medico."],"kw":"prevenzione rottura crociato giovani, atterraggio ginocchio, crociato pubertà"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Frontiers in Sports and Active Living",h:"Riparazione primaria del LCA con suture tape: selettiva, non sostitutiva",v:"Rassegna narrativa (testo completo aperto): la riparazione con nastro di sutura regge per le lesioni prossimali acute con buon tessuto; nei giovani e nelle attività ad alta richiesta i fallimenti riportati sono più alti. Non è una sostituzione della ricostruzione.",ax:"Alabid, Hamdy, Patni, Yousef, George, Menon, Elayyan",date:"set 2026",meta:"rassegna narrativa (PubMed, Scopus, Google Scholar, 2015-maggio 2026), nessuna sintesi quantitativa · [V]",pmid:'42819348',doi:'10.3389/fspor.2026.1893928',journal:"Frontiers in Sports and Active Living",authors:"Alabid I, Hamdy HA, Patni MM, Yousef AJ, George BT, Menon A, Elayyan KW",design:"Rassegna narrativa con ricerca strutturata su PubMed, Scopus, Google Scholar e screening manuale delle bibliografie, soprattutto 2015-maggio 2026, con studi clinici, di imaging, artroscopici e biomeccanici. Esamina indicazioni e controindicazioni alla riparazione primaria del LCA, la logica biologica e biomeccanica del rinforzo con nastro di sutura, gli esiti clinici e comparativi, i predittori di fallimento e le lacune; il restauro con scaffold (BEAR) è trattato a parte. Nessun protocollo registrato, nessuna valutazione del rischio di bias e nessuna sintesi quantitativa nel testo.",pop:"Nessuna popolazione propria: la revisione raccoglie studi singoli su lesioni prossimali del LCA (adulti, alcuni adolescenti e militari) e li riporta in tabella. Il numero totale di studi inclusi non è riportato nell'abstract.",results:"Dati riportati dalla revisione da studi singoli, senza intervalli di confidenza né p nel testo. Riparazione con suture tape: 6 fallimenti su 56 riparazioni consecutive (10,7%) a 3,2 anni di follow-up medio (Jonkergouw); 34 pazienti analizzati a 5 anni, KOOS medio da 48,7 a 88,5 e 6 re-rotture (17,6%), più frequenti nei più giovani e con punteggio Marx iniziale più alto (Hopper); 12 fallimenti su 46 (26,1%) in militari in servizio attivo (Cruz). Su 353 lesioni acute di LCA in RM: tipo I prossimale 16%, tipo II 27%, tipo III a metà legamento 52%. In un RCT sulla stabilizzazione dinamica intralegamentosa (tecnica distinta dal nastro), re-rottura omolaterale 8,7% contro 19,0% con ricostruzione all-inside. Dimensioni dell'effetto aggregate e intervalli di confidenza non riportati.",concl:"Gli autori concludono che la riparazione primaria con rinforzo di nastro di sutura è una strategia di preservazione selettiva e non un sostituto generale della ricostruzione; servono studi comparativi più ampi, con indicazioni, tecniche, riabilitazione e definizioni di fallimento standardizzate, per stabilirne il ruolo a lungo termine.",limits:"Rassegna narrativa: nessun protocollo registrato, nessuna valutazione del rischio di bias, selezione degli studi interpretativa · i numeri vengono da studi singoli piccoli, per lo più non randomizzati, con tecniche, selezione e definizioni di fallimento diverse: gli stessi autori scrivono che non permettono conclusioni di equivalenza con la ricostruzione · nessuno studio citato confronta riparazione con nastro e ricostruzione con il tuo innesto o con il LET · testo completo aperto su PMC: numeri dal testo, non solo dall'abstract.",perte:"Non è la tua tecnica: tu ricostruisci con retto femorale/tendine quadricipitale e fai il Lemaire onlay su tutti. Serve come risposta all'alternativa «tessuto proprio» (di cui DiFelice è citato come studio fondativo, 10 su 11 con buon esito): applicabile solo a lesioni prossimali acute con buon tessuto, cioè una minoranza (tipi I e II 43% nella prevalenza riportata), e con fallimenti riportati più alti sotto i 21 anni e nell'alta richiesta. Nessun dato sul LET né sull'innesto quadricipitale: non muove T1."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Orthopedics",h:"LCA primario: spendere di più non migliora l'esito; l'alloinnesto ha meno valore",v:"491 pazienti e 24 chirurghi in un centro chirurgico ambulatoriale statunitense: costi totali e variazione del KOOS a 2 anni poco correlati; tipo di innesto, tempo operatorio, riparazione meniscale e impianti associati al valore, con l'alloinnesto più basso degli autoinnesti (p=0,003).",ax:"Kleinsmith, Wolff, Lawhorn, Borgida, Agoro, Huyke-Hernandez, Cunningham",date:"ott 2026",meta:"analisi retrospettiva di un database di PROM, 491 pazienti, 24 chirurghi, costi time-driven · [III]",pmid:'42821787',doi:'10.3928/01477447-20260825-01',journal:"Orthopedics",authors:"Kleinsmith RM, Wolff S, Lawhorn HP, Borgida JS, Agoro KS, Huyke-Hernandez FA, Cunningham BP",design:"Analisi retrospettiva del database di PROM di un centro chirurgico ambulatoriale (2009-2022): ricostruzioni primarie unilaterali del LCA singolo-legamento per lesione acuta (meno di 6 mesi) con KOOS e SANE disponibili. Costi calcolati con time-driven activity-based costing, in dollari 2024. Esito primario: quoziente di valore a 2 anni, cioè variazione del KOOS divisa per il costo totale. Metodo statistico non riportato nell'abstract.",pop:"491 pazienti e 24 chirurghi, un solo centro chirurgico ambulatoriale statunitense, ricostruzione primaria del LCA. Età, sesso, tipi di autoinnesto e numero di alloinnesti non riportati nell'abstract.",results:"Costi totali di cura e variazione del KOOS a 2 anni correlati debolmente (coefficiente 0,14; per il SANE 0,13; tipo di coefficiente e intervalli di confidenza non riportati nell'abstract). Fattori associati al valore a 2 anni: tempo operatorio, riparazione meniscale concomitante, tipo di innesto e impianti (tutti con p ≤ 0,038); l'alloinnesto ha un valore inferiore agli autoinnesti (p=0,003). Dimensioni dell'effetto per fattore e direzione per riparazione meniscale e impianti non riportate nell'abstract.",concl:"Gli autori scrivono che l'analisi del valore a livello di paziente ha quantificato il valore a 2 anni e identificato fattori istituzionali influenti nella ricostruzione primaria, che costi di cura più alti non hanno prodotto esiti migliori, e che la metodologia va applicata e studiata ancora in ortopedia.",limits:"Un solo sistema statunitense: i costi non sono trasferibili alle tariffe svizzere · retrospettivo e non randomizzato: innesto, tempo operatorio e riparazione meniscale dipendono dall'indicazione e dal chirurgo, quindi le associazioni non sono causali · l'abstract non dice quali autoinnesti, quanti alloinnesti né la dimensione degli effetti · articolo non open access: testo completo non aperto.",perte:"Tocca due punti della tua pratica ma senza darti il dato che serve: il tipo di innesto (l'alloinnesto rende meno valore degli autoinnesti, ma l'abstract non separa i tipi di autoinnesto, quindi il retto femorale/quadricipite non è identificabile) e la riparazione meniscale concomitante (associata al valore, direzione non riportata). Nessun dato sul LET né sui costi in Svizzera."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Frontiers in Medicine",h:"LCA leso: meno forza in estensione e più co-contrazione degli ischiocrurali",v:"114 pazienti con rottura isolata (55 acuti, 59 cronici) e 57 controlli: coppia di picco in estensione più bassa negli acuti e ancora ridotta nei cronici; co-contrazione degli ischiocrurali più alta nei cronici. Entrambe correlate al KOOS (studio trasversale).",ax:"Yu, Qu, Liang, Tong, Xing, Zhang, Guo",date:"set 2026",meta:"studio trasversale con controlli, 114 pazienti con LCA leso e 57 controlli sani · [III]",pmid:'42819099',doi:'10.3389/fmed.2026.1945491',journal:"Frontiers in Medicine",authors:"Yu H, Qu S, Liang P, Tong S, Xing X, Zhang L, Guo L",design:"Studio trasversale (livello III) su tre gruppi: coppia isometrica massima volontaria e isocinetica concentrica a 60°/s in estensione e flessione; elettromiografia di superficie per la co-contrazione antagonista di ischiocrurali e quadricipite; KOOS nei soli pazienti con LCA leso. Confronti per gruppo e sesso, correlazioni di Spearman e regressione lineare multipla.",pop:"114 pazienti con rottura isolata monolaterale del LCA (55 acuti, meno di 6 settimane; 59 cronici, più di 6 mesi) e 57 controlli sani; centro di medicina dello sport di Chongqing, Cina. Età, trattamento e innesto non riportati nell'abstract.",results:"Coppia di picco in estensione dell'arto leso (acuti, cronici, controlli), in N·m/kg: uomini 2,23 ± 0,64 · 3,05 ± 0,60 · 3,48 ± 0,59; donne 1,51 ± 0,58 · 2,21 ± 0,61 · 3,05 ± 0,56 (tutti p ≤ 0,001). Co-contrazione combinata degli ischiocrurali: uomini 14,32 ± 4,91% · 23,05 ± 5,87% · 7,89 ± 4,34%; donne 27,18 ± 5,25% · 41,28 ± 6,34% · 16,54 ± 5,28% (tutti p < 0,001). Correlazioni con i sottopunteggi KOOS: coppia media in estensione da 0,381 a 0,562; co-contrazione da −0,326 a −0,541 (p < 0,05). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che il LCA leso si associa a minore forza e maggiore co-contrazione antagonista, con profili diversi per cronicità: il deficit di forza è massimo negli acuti, la co-contrazione nei cronici; più co-contrazione e meno coppia in estensione si associano a una funzione riferita peggiore.",limits:"Trasversale: non dice se il deficit preceda la lesione né se la co-contrazione sia causa o compenso · acuti e cronici sono pazienti diversi, non gli stessi seguiti nel tempo · pazienti non operati: nessun dato dopo la ricostruzione, né sul prelievo dell'innesto · correlazioni di entità moderata (valore assoluto da 0,33 a 0,56) · un solo centro · articolo ad accesso aperto, testo completo non aperto: numeri da abstract.",perte:"Riguarda la fase prima della ricostruzione, non il tuo innesto: il deficit di estensione è già marcato nei primi mesi e non è recuperato nei cronici. Collegamento indiretto con T3 (criterio di rientro): la forza in estensione è la grandezza su cui poggia l'LSI, qui misurata nei non operati. Non dice nulla sul prelievo del quadricipite né sul recupero dopo il tuo innesto."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"The Knee",h:"Ginocchio nativo sotto carico: la geometria articolare orienta l'allineamento",v:"Revisione sistematica descrittiva di 39 studi (imaging in vivo e cadavere): sotto carico la superficie mediale della tibia diventa più parallela al suolo; slope e posizione antero-posteriore del contatto sono legati a rotazione e sublussazione. Nessun dato quantitativo aggregato.",ax:"Ardiri, Ciccolo, Petrillo",date:"ott 2026",meta:"revisione sistematica descrittiva (mappa degli studi), 39 record, nessuna graduazione delle prove · [V]",pmid:'42822121',doi:'10.1016/j.knee.2026.104649',journal:"The Knee",authors:"Ardiri D, Ciccolo G, Petrillo S",design:"Revisione sistematica con ricerca su «un ampio corpus accademico» seguita da verifica bibliografica manuale su PubMed, pagine degli editori e DOI. Studi di imaging in vivo e cadaveri intatti su ginocchio nativo adulto; misure: obliquità della linea articolare, allineamento frontale, contatto mediale e laterale, estrusione meniscale, slope tibiale posteriore, traslazione tibiale. Studi mappati per dominio meccanicistico, non graduati come classi di evidenza.",pop:"Studi su ginocchio nativo adulto, in vivo e su cadavere intatto: 39 record esaminati. Numero di partecipanti e database interrogati non riportati nell'abstract.",results:"Nessun risultato quantificato nell'abstract: 39 studi riportati in una mappa studio per studio. Sotto carico la superficie articolare mediale della tibia prossimale diventa più parallela al suolo; la compressione assiale produce orientamento in varo e traslazione mediale nella flessione precoce; slope tibiale posteriore, asimmetria mediale-laterale dello slope e posizione antero-posteriore della tibia sono legati a carico, rotazione e sublussazione. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori interpretano il fenomeno come una risposta geometrica al carico del ginocchio nativo: altezze di contatto diverse fra mediale e laterale producono inclinazione coronale, la posizione antero-posteriore del contatto produce il comportamento sagittale. Lo ritengono applicabile soprattutto a ginocchia con contenimento meniscale conservato e congruenza da integra a lievemente degenerata; chiedono studi che misurino insieme le stesse variabili con un protocollo standard.",limits:"Ricerca su «un ampio corpus» senza database né criteri di inclusione nell'abstract: la riproducibilità non è verificabile · mappa descrittiva, senza graduazione della qualità né sintesi quantitativa: dice che il meccanismo è coerente, non quanto pesi · solo ginocchio nativo: nessuna protesi, osteotomia o LCA operato · gli stessi autori limitano l'applicabilità ai ginocchi con menisco contenuto · articolo non open access: testo completo non aperto.",perte:"Tocca lo slope e l'osteotomia (slope posteriore, asimmetria mediale-laterale e estrusione meniscale fra i parametri mappati) e, per la protesi, il dibattito sull'allineamento: il titolo contrappone congruenza articolare e neutralità. Non dà una soglia di slope né dati sul tuo gesto correttivo, e non è uno studio di esiti: serve come cornice meccanica, non come indicazione."},{n:5,mono:"m-gray",dot:"gray",sec:"res",j:"Drug Design, Development and Therapy",h:"Protesi totale: bupivacaina liposomiale, dolore a 24 ore più basso di 0,5 punti",v:"RCT monocentrico, 60 pazienti (30 per braccio), blocco del canale degli adduttori più iPACK: VAS a riposo a 24 ore 2,4 ± 0,8 contro 2,9 ± 1,1 (differenza −0,52; IC 95% da −1,01 a −0,02). Gli autori stessi chiedono cautela sul peso clinico.",ax:"Ren, Zeng, Zhao, Zhang, Zhou, Xie",date:"set 2026",meta:"RCT monocentrico, valutatore in cieco, 60 pazienti (30 per braccio) · [II]",pmid:'42820104',doi:'10.2147/DDDT.S643205',journal:"Drug Design, Development and Therapy",authors:"Ren P, Zeng L, Zhao L, Zhang L, Zhou X, Xie Y",design:"RCT monocentrico, valutatore degli esiti in cieco, registrato nel Chinese Clinical Trial Registry (ChiCTR2500115826, 31 dicembre 2025). Protesi totale di ginocchio con blocco del canale degli adduttori e infiltrazione iPACK: bupivacaina liposomiale più bupivacaina cloridrato, oppure bupivacaina cloridrato più desametasone. Esito primario: VAS a riposo a 24 ore. Secondari: dolore ad altri tempi, emodinamica e oppioidi intraoperatori, forza del quadricipite, consumo di PCIA, analgesia di soccorso, eventi avversi da oppioidi.",pop:"60 pazienti analizzati (30 per braccio) sottoposti a protesi totale di ginocchio, un solo centro cinese. Età, sesso e tipo di anestesia non riportati nell'abstract.",results:"VAS a riposo a 24 ore 2,4 ± 0,8 (liposomiale) contro 2,9 ± 1,1 (cloridrato più desametasone): differenza media −0,52 punti (IC 95% da −1,01 a −0,02; p=0,040). Forza del quadricipite a favore del braccio liposomiale a 12 ore (valori non riportati nell'abstract). Analgesia di soccorso più frequente nel braccio desametasone: RR 2,40 (IC 95% 1,12-5,14; p=0,024); a 48 ore 3/30 contro 11/30 (p=0,030). Volume cumulativo di PCIA a 48 ore 99,75 (96,00-100,00) mL contro 100,00 (100,00-100,00) mL (p<0,001).",concl:"Gli autori scrivono che il regime con bupivacaina liposomiale si associa a meno dolore in alcuni momenti e a migliore forza del quadricipite a 12 ore, con un possibile beneficio analgesico precoce nelle prime 72 ore; la rilevanza clinica della differenza di dolore va interpretata con cautela.",limits:"L'IC arriva a −0,02: il limite sfiora lo zero e la soglia di rilevanza clinica non è riportata nell'abstract · il confronto cambia due cose insieme (formulazione liposomiale e assenza di desametasone), quindi non isola l'effetto della formulazione · 60 pazienti, un centro, un solo esito primario a 24 ore; correzione per confronti multipli sui molti esiti secondari non riportata nell'abstract · il volume di PCIA è vicino a 100 mL in entrambi i bracci: la differenza è significativa ma di scarso peso pratico · date di arruolamento non riportate, quindi non si può dire se la registrazione sia stata prospettica · testo completo non aperto.",perte:"Non tocca la tua tecnica: riguarda l'analgesia perioperatoria della protesi totale (anche con VELYS). Un effetto di mezzo punto con IC fino a zero non cambia da solo il protocollo e non dice nulla sul recupero funzionale a distanza; utile soprattutto per un confronto con l'anestesista."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"International Orthopaedics",h:"Registro irlandese, primo decennio: Oxford Knee Score da 19,5 a 40,5 a cinque anni",v:"18.102 protesi totali di ginocchio primarie su 43.291 interventi, 17 ospedali, 2015-2024: revisione a un anno 0,8%, infezione a 30 giorni 0,5%. Copertura nazionale incompleta: gli autori chiedono cautela sulle revisioni.",ax:"Farrell, Davey, Hickey, Browne, Brent, O'Donovan, El-Hadidi, Quinlan",date:"set 2026",meta:"registro descrittivo, 43.291 interventi (18.102 protesi totali di ginocchio primarie), 17 ospedali · [III]",pmid:'42803958',doi:'10.1007/s00264-026-07044-2',journal:"International Orthopaedics",authors:"Farrell C, Davey MS, Hickey P, Browne D, Brent L, O'Donovan C, El-Hadidi S, Quinlan JF",design:"Analisi descrittiva retrospettiva di dati aggregati del rapporto nazionale dell'Irish National Orthopaedic Register 2015-2024 e delle sue appendici: demografia, attività, impianti, fissazione, PROM (Oxford Hip Score, Oxford Knee Score, EQ-5D-5L) ed esiti clinici (infezione del sito a 30 giorni, lussazione, frattura periprotesica, tromboembolismo, mortalità, revisione a un anno). Il registro nasce dopo il richiamo della protesi d'anca ASR metallo-metallo.",pop:"43.291 interventi in 17 ospedali partecipanti: 22.249 protesi totali d'anca primarie (51%), 18.102 protesi totali di ginocchio primarie (42%), 1.864 revisioni d'anca (4%) e 1.076 revisioni di ginocchio (3%); volume annuo da 841 casi nel 2015 a 10.266 nel 2024. Ingresso scaglionato degli ospedali e copertura nazionale incompleta.",results:"Oxford Knee Score medio da 19,5 prima dell'intervento a 40,5 a cinque anni; EQ-5D-5L da 0,364 a 0,793 dopo protesi totale di ginocchio. Revisione a un anno 0,8% dopo protesi totale di ginocchio (1,0% d'anca); infezione del sito chirurgico a 30 giorni 0,5% per entrambe; mortalità a 30 giorni 0,1% nel complesso. Intervalli di confidenza non riportati nell'abstract (dati aggregati, analisi descrittiva).",concl:"Gli autori scrivono che nel primo decennio il registro ha ampliato la copertura e prodotto dati su impianti, PROM ed esiti negli ospedali partecipanti; per l'ingresso scaglionato e la copertura incompleta i risultati rappresentano gli ospedali partecipanti e non il quadro nazionale, e le stime di revisione vanno lette con cautela per il denominatore incompleto.",limits:"Descrittivo, su dati aggregati: nessun gruppo di confronto né aggiustamento · copertura incompleta e ingresso scaglionato degli ospedali: il denominatore delle revisioni è incompleto, come dichiarano gli autori · revisione a un solo anno: non misura la durata dell'impianto · l'abstract non distingue robot, tipi di impianto di ginocchio né fissazione nel ginocchio (la fissazione è riportata per l'anca) · articolo non open access: testo completo non aperto.",perte:"Dato di contesto per la tua protesi totale, non un confronto: un riferimento di un sistema diverso dal tuo (revisione a un anno 0,8%, OKS a cinque anni 40,5). Non distingue il robot, quindi non aggiunge né toglie nulla al lavoro del BMJ di ieri sulla protesi robotica."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Adesiolisi dopo protesi: più flessione conservata con chirurgo formato in artroscopia",v:"94 adesiolisi artroscopiche per rigidità dopo protesi totale, un sistema accademico: perdita di flessione rispetto al valore intraoperatorio 4,85° contro 15,98° (p=0,006) col chirurgo con fellowship artroscopico; 8 revisioni su 94, 6 nel gruppo senza fellowship. Associazione, non causa.",ax:"Bcharah, Cancio-Bello, Nguyen, Lin, Hevesi, Ortiguera, Chhabra, Bingham",date:"set 2026",meta:"coorte retrospettiva comparativa, 94 adesiolisi (46 contro 48), Mayo Clinic, 1989-2025 · [III]",pmid:'42820114',doi:'10.1002/ars2.70088',journal:"Arthroscopy, Sports Medicine, and Rehabilitation",authors:"Bcharah G, Cancio-Bello A, Nguyen C, Lin E, Hevesi M, Ortiguera CJ, Chhabra A, Bingham J",design:"Coorte retrospettiva comparativa (livello III) in un sistema accademico multi-sede (Mayo Clinic), da agosto 1989 a maggio 2025, follow-up minimo 3 mesi. Gruppi per formazione del chirurgo: fellowship in artroscopia contro nessuna formazione o formazione non artroscopica. Esiti: guadagno intraoperatorio e ritenzione postoperatoria di arco di movimento rispetto al valore intraoperatorio e a quello prima della protesi; revisioni e infezioni periprotesiche.",pop:"94 adesiolisi artroscopiche per rigidità dopo protesi totale primaria di ginocchio: 48 (51,1%) eseguite da chirurghi senza formazione artroscopica, 46 da chirurghi con fellowship. Età, intervallo dalla protesi, tipo di protesi e follow-up medio non riportati nell'abstract.",results:"Guadagno intraoperatorio di flessione 35,2° (con fellowship) contro 31,1° (senza), p=0,130; di estensione 2,43° contro 3,91° (p=0,079). A distanza, rispetto al valore intraoperatorio: flessione −4,85° contro −15,98° (p=0,006); estensione +0,50° contro −1,58° (p=0,036). Rispetto al valore prima della protesi: flessione +1,66° contro −21,76° (p<0,001). Revisioni 8 su 94 (8,51%), 6 dopo chirurghi senza fellowship; un caso di infezione periprotesica. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che l'adesiolisi eseguita da chirurghi con fellowship in artroscopia si associa a una ritenzione dell'arco di movimento postoperatorio significativamente migliore rispetto a chirurghi senza fellowship, nell'artrofibrosi dopo protesi totale.",limits:"Retrospettivo su 36 anni: tecniche, protesi e indicazioni cambiano nel tempo e l'abstract non riporta aggiustamenti · la formazione del chirurgo è confusa con volume, epoca, tecnica e selezione dei pazienti: l'associazione non è causale · follow-up, intervallo dalla protesi e tipo di protesi non riportati · 8 revisioni in tutto: conteggi troppo piccoli per un confronto (vedi studio muto) · testo completo non aperto.",perte:"Fuori dalla tua pratica corrente: è una complicanza della protesi totale (artrofibrosi), non dell'impianto o del robot, e l'abstract non riporta il tipo di protesi. Il dato da ricordare è che il guadagno ottenuto in sala si perde in parte nel tempo (flessione −4,85° e −15,98° rispetto al valore intraoperatorio); Mario Hevesi, coautore, firma anche un lavoro sulla riparazione della radice meniscale (ancoraggio intratunnel contro pull-through transtibiale, PMID 42782213)."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of Sports Sciences",h:"Atterraggio su una gamba: più carico prima della pubertà che nelle post-puberi",v:"69 giovani in laboratorio (9-16 per gruppo) con motion capture: le ragazze post-puberi non mostrano la biomeccanica attesa per un rischio di LCA più alto; i pre-puberi hanno forze verticali e momenti al ginocchio relativi maggiori. Gruppi piccoli, nessun infortunio osservato.",ax:"Butcher, Ward, Clissold, Richards, Hébert-Losier",date:"ott 2026",meta:"studio di laboratorio trasversale, 69 partecipanti (9-16 per gruppo) · [IV]",pmid:'42821594',doi:'10.1080/02640414.2026.2741489',journal:"Journal of Sports Sciences",authors:"Butcher AJ, Ward S, Clissold T, Richards J, Hébert-Losier K",design:"Studio di laboratorio trasversale su due compiti, atterraggio da salto su una gamba e atterraggio con cambio di direzione, con motion capture 3D e pedane di forza; ANOVA 2×3 per sesso e stadio di maturazione (Tanner, picco di velocità di crescita, scala osservazionale della maturazione puberale). La biomeccanica è un indicatore indiretto del rischio di LCA: nessun infortunio osservato.",pop:"69 partecipanti: maschi 16 pre-puberi, 11 mid-puberi, 11 post-puberi; femmine 10, 9 e 10. Età, sport e livello non riportati nell'abstract; gruppo della Nuova Zelanda (Tauranga).",results:"Nessun valore numerico nell'abstract: le ragazze post-puberi non mostrano biomeccanica indicativa di un rischio di LCA comparativamente più alto; i pre-puberi mostrano forze verticali di reazione e momenti al ginocchio relativi maggiori rispetto agli altri gruppi. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori suggeriscono che screening e prevenzione prima della pubertà potrebbero aiutare a sviluppare schemi di movimento più sicuri e ridurre il rischio di LCA con la maturazione.",limits:"Trasversale: confronta giovani diversi e non li segue nel tempo · nessun infortunio osservato: la biomeccanica è un indicatore indiretto del rischio · gruppi di 9-16 partecipanti per cella, troppo piccoli per escludere differenze (vedi studio muto) · compito di laboratorio, non gioco · sport e livello non riportati · testo completo non aperto.",perte:"Fuori dal tuo campo operatorio (prevenzione, anche prima dei 14 anni), ma tocca l'adolescente che operi dai 14 in su: il lavoro propone di intervenire prima della maturazione, non dopo la lesione. Nessun dato su innesto, LET o recidiva."}];
var SUGGQ=[{k:"kol",n:"Mario Hevesi",w:"Mayo Clinic, Rochester (Minnesota, Stati Uniti) — coautore del lavoro di oggi sull'adesiolisi dopo protesi totale (PMID 42820114) e firmatario di lavori sulla radice meniscale (PMID 42782213, ancoraggio intratunnel contro pull-through transtibiale; PMID 42750098) e sull'instabilità rotulea (PMID 42732467); corrispondenza tecnica con la tua rifissazione della radice meniscale con tecnica transtibiale. Sostituisce David W. Murray (1 ottobre, nessun segnale dell'utente arrivato per farlo ruotare)."}];
var BRIEF_TEXT="Il lavoro del giorno è fuori dalla tua pratica corrente ma dentro un tema che segui: la riparazione primaria del crociato anteriore con rinforzo di nastro di sutura. È una rassegna narrativa a testo completo aperto, su Frontiers in Sports and Active Living. Dagli studi singoli che cita riporta fallimenti del dieci virgola sette per cento su cinquantasei riparazioni a tre anni circa e del diciassette virgola sei per cento su trentaquattro pazienti a cinque anni, più frequenti nei giovani e nell'alta richiesta, e conclude che è una strategia selettiva, non un sostituto della ricostruzione. Il limite: nessun protocollo registrato, studi piccoli e per lo più non randomizzati, nessun dato sul tuo innesto quadricipitale né sul Lemaire onlay.\n\nSeconda scheda, sempre sul crociato: un'analisi di quattrocentonovantuno ricostruzioni in un centro americano trova che costi totali e miglioramento del KOOS a due anni sono poco correlati, con l'alloinnesto a valore inferiore agli autoinnesti; ma l'abstract non separa i tipi di autoinnesto, quindi il tuo non è identificabile.\n\nLe altre schede: uno studio trasversale con controlli mostra nel crociato leso meno forza in estensione e più co-contrazione degli ischiocrurali; una revisione descrittiva sul ginocchio nativo sostiene che sotto carico la geometria articolare, slope compreso, orienta l'allineamento; un piccolo trial sull'analgesia della protesi totale trova mezzo punto di dolore in meno a ventiquattro ore con la bupivacaina liposomiale, con un intervallo che arriva a zero; il registro irlandese, al primo decennio, riporta dopo la protesi totale di ginocchio una revisione a un anno dello zero virgola otto per cento; una coorte sull'adesiolisi artroscopica dopo protesi associa la formazione artroscopica del chirurgo a una flessione meglio conservata, ma con sole otto revisioni in tutto; e uno studio di laboratorio su sessantanove giovani suggerisce di fare prevenzione prima della pubertà, con gruppi troppo piccoli per escludere differenze.\n\nNessun richiamo nuovo: i richiami del nucleo sorvegliato restano quelli già noti. Nessuna ritrattazione nuova sul citato. Nessuna voce nuova fra le linee guida degli ultimi sessanta giorni. Oggi nessuna tensione si è mossa.";
var BRIEF_DIALOGO=[{"chi":"A","t":"Il lavoro di oggi è fuori dalla tua pratica corrente: la riparazione primaria del crociato anteriore con nastro di sutura, in una rassegna narrativa a testo completo aperto."},{"chi":"B","t":"Quindi niente a che vedere con il tuo innesto quadricipitale?"},{"chi":"A","t":"Esatto: nessuno degli studi citati riguarda l'innesto quadricipitale o il Lemaire onlay. Però il tema lo segui: la riparazione, con DiFelice citato come studio fondativo."},{"chi":"B","t":"Che numeri riporta?"},{"chi":"A","t":"Dagli studi singoli: fallimento del dieci virgola sette per cento su cinquantasei riparazioni a tre anni circa, e del diciassette virgola sei per cento su trentaquattro pazienti a cinque anni. Più frequente nei giovani e nell'alta richiesta."},{"chi":"B","t":"E la conclusione?"},{"chi":"A","t":"Strategia selettiva, per lesioni prossimali acute con buon tessuto, non un sostituto della ricostruzione. E su una serie di risonanze, circa quattro rotture su dieci hanno quella sede."},{"chi":"B","t":"Il limite?"},{"chi":"A","t":"Rassegna narrativa, senza protocollo né valutazione del rischio di bias, con studi piccoli e per lo più non randomizzati: gli stessi autori dicono che non permettono di concludere l'equivalenza con la ricostruzione."},{"chi":"B","t":"Seconda scheda?"},{"chi":"A","t":"Un'analisi di quattrocentonovantuno ricostruzioni del crociato in un centro americano: costi totali e miglioramento del KOOS a due anni sono poco correlati, e l'alloinnesto ha un valore inferiore agli autoinnesti."},{"chi":"B","t":"Quindi per il tuo retto femorale o quadricipite?"},{"chi":"A","t":"Non lo si può dire: l'abstract non separa i tipi di autoinnesto, e i costi sono quelli di un sistema statunitense."},{"chi":"B","t":"Richiami, ritrattazioni, linee guida?"},{"chi":"A","t":"Nessun richiamo nuovo, nessuna ritrattazione e nessuna voce nuova fra le linee guida. Per le altre sei schede, apri l'app."}];
